    "description": "APP端： 5+api 文档 https://www.html5plus.org/doc/zh_cn/video.html#plus.video.createLivePusher image.png 就是使用这个api调用原生的camera完成。并且可以直接在预览模式下完成快照，也不需要真实的推流地址。 1、请保证本人验证。 2、请使头像正面位于画框中。 3、请使头像尽量清晰。 4、请保证眼镜不反光，双眼可见。 5、请保证无墨镜，口罩，…",
    "content": "APP端： 因为APP端无法使用uni的camera组件，最开始考虑使用内嵌webview的方式，通过原生dom调用video渲染画面然后通过canvas截图。但是此方案兼容性在ios几乎为0，如果app只考虑安卓端的话可以采用此方案。后面又想用live-pusher组件来实现，但是发现快照api好像需要真实流地址才能截取图像。因为种种原因，也是安卓ios双端兼容性不佳。最终决定采用5+api实现。经实测5+api兼容性还算可以，但是毕竟是调用原生能力，肯定是没有原生开发那么丝滑的，难免会出现一些不可预测的兼容性问…"
