    "content": "2026年适逢中国漫画百年。10月31日，上海朱屺瞻艺术馆携手丰子恺研究会推出的“一钩新月天如水——丰子恺艺术文献展”正式对外展出。 与以往侧重呈现丰子恺漫画成就的展览不同，本次展览将视角收束到“文化在地性”上，以文献梳理的方式回溯他1924年底至1932年在虹口的艺术行迹，试图还原“子恺漫画”生成的具体现场。展览追问的是：一位画种的命名者，如何在一座城市的具体街区、校舍与刊物网络中，逐步完成自己的艺术语言。 丰子恺先生（1898-1975） 《人散后，一钩新月天如水》展出现场 朱屺瞻艺术馆副馆长、展览策展人马艳在…"
