    "description": "2026年11月01日 在广东省河源市东源县柳城镇的万绿智慧农场内，成片的航天水稻“华航香银针”已经进入收割期。 航天水稻是通过航天育种和现代生物技术相结合育成的多基因优良品种。水稻种子搭乘航天器进入太空后，在宇宙射线、微重力等特殊环境影响下，经诱发产生有利的基因变化，被培育成新品种。 “进入太空的种子不会马上变成良种，回到地面后，还要一代代持续种植观察。我们结合河源当地的气候、土壤条件，重点观察种子在产量、米质、抗病、抗倒伏等方面的实…",
    "content": "2026年11月01日 在广东省河源市东源县柳城镇的万绿智慧农场内，成片的航天水稻“华航香银针”已经进入收割期。 航天水稻是通过航天育种和现代生物技术相结合育成的多基因优良品种。水稻种子搭乘航天器进入太空后，在宇宙射线、微重力等特殊环境影响下，经诱发产生有利的基因变化，被培育成新品种。 “进入太空的种子不会马上变成良种，回到地面后，还要一代代持续种植观察。我们结合河源当地的气候、土壤条件，重点观察种子在产量、米质、抗病、抗倒伏等方面的实际表现。”华南农业大学国家植物航天育种工程技术研究中心副主任刘永柱说。 “‘华航…"
