    "content": "2026年11月01日 近日，湖北汽车工业学院、济宁医学院等多所高校相继发文规范课堂教学，明确“严禁全程依赖PPT”，杜绝“念课件”等，引发关注。 对此，有人拍手叫好，也有人认为不该把PPT一棍子打死。事实上，几所高校的新规都没有否定PPT的辅助价值，而是剑指“全程依赖”四个字。部分教师上课从头到尾念PPT，公式不推导，术语不解释；台下学生用拍照取代记笔记，缺少互动思考。更有甚者，个别老师“一份课件年年用”，内容跟不上学科发展，脱离学生实际学情，课程被打上“水课”标签。 “全程依赖PPT”背后所折射的，实则是部分教…"
