    "content": "2026年11月01日 今年是孙中山先生诞辰160周年。然而，台陆委会近日称，凡是要申请赴大陆参加孙中山先生诞辰160周年纪念活动的人员，将会被“不予许可”，其背叛民族、背叛历史，图谋分裂国家、升高两岸对立对抗的险恶用心暴露无遗。 孙中山先生是伟大的民族英雄、伟大的爱国主义者、中国民主革命的伟大先驱，他的精神和情怀受到两岸同胞敬仰。 回顾往昔，台当局多次妄图“去孙中山化”：赖清德任台南市市长时，曾坚持拆掉孙中山先生铜像，引发民众连续数日扎营守护；绿营曾提案“修法”，要求取消悬挂孙中山先生遗像；“独派”曾提议“中山路…"
