    "description": "2026年11月01日 日前，“家国同心向复兴——中国侨联成立70周年主题展”在中国华侨历史博物馆举办。展览集中展出藏品超400件（套），以珍贵实物、文献与影像，呈现中国侨联成立70年来，团结引领广大侨胞和归侨侨眷，服务国家发展大局的光辉历程。展览将持续至明年2月。图为观众在展览上参观。 新华社记者 张 帆摄 2026-11-01 00:00:00:0 30188742 10http://paper.people.com.cn/rmrb…",
