    "author": "",
    "description": "2026年11月01日 10月31日，第六届粤港澳大湾区文化艺术节在深圳滨海艺术中心启幕，香港管弦乐团、澳门戏剧农庄等10余家港澳院团携精品力作北上展演；此前，舞剧《咏春》、音乐剧《雄狮少年》等广东优秀剧目早已南下赴港澳巡演，广受好评。你来我往的戏潮与人潮，聚起湾区文艺的满满人气。 聚人气更聚人心。以文化人、润物无声，推动粤港澳三地从“地理相邻”走向“人心相依”，需要在强化文化艺术交流上下功夫，拓展平台、创新机制，让一台台好戏成为促进民…",
    "content": "2026年11月01日 10月31日，第六届粤港澳大湾区文化艺术节在深圳滨海艺术中心启幕，香港管弦乐团、澳门戏剧农庄等10余家港澳院团携精品力作北上展演；此前，舞剧《咏春》、音乐剧《雄狮少年》等广东优秀剧目早已南下赴港澳巡演，广受好评。你来我往的戏潮与人潮，聚起湾区文艺的满满人气。 聚人气更聚人心。以文化人、润物无声，推动粤港澳三地从“地理相邻”走向“人心相依”，需要在强化文化艺术交流上下功夫，拓展平台、创新机制，让一台台好戏成为促进民心相通的重要纽带。 聚人心，文化同源是根基。粤港澳同饮一江水，文化同源、人缘相亲…"
