    "content": "2026年11月01日 走进位于香港尖沙咀海滨的香港艺术馆，阳光透过落地玻璃洒进展厅。 艺术馆四楼静观楼藏品厅里，正在举行的“难得清风——静观楼藏扇精选”展吸引不少观众驻足。展柜前，人们细看扇面上的一笔一画。张大千的《黄山扰龙松》，水墨与设色相映，松枝虬曲盘旋，山石气韵生动，方寸之间仿佛藏着黄山的苍劲风骨；赵之谦的《墨菊图》，笔墨古雅，菊枝舒展，将文人寄情花木的雅趣凝于纸上。 一把把折扇次第铺展，山水花鸟、笔墨意趣各有千秋，让人不禁想象昔日文人雅士执扇临风、挥毫题画的闲情逸致。展览从香港收藏家、摄影家黄贵权设立的私…"
