    "content": "2026年11月01日 “锣鼓敲起来，唢呐吹起来，敲起来吹起来新人乐开怀……”山西省运城市万荣县王显村的农家小院里锣鼓声声，欢快的民歌响彻庭院，20余名乡村妇女身着红色旗袍，翩翩起舞，笑容灿烂，洋溢着昂扬的精气神。 这是当地自发组织的“乐善万荣妈妈团”。一场接地气的乡土演出，取代了以往大操大办的传统婚礼形式，成了乡村婚礼上最动人的新风景。 王麦菊家即将迎来喜事，她跟老伴商量：以往村里嫁娶，总要花钱外请鼓队、歌舞团，少则几千、多则上万，铺张浪费还少了乡土温情。王麦菊想到了村里的“妈妈团”。 婚礼前一晚，“妈妈团”连续…"
