    "content": "新华社广州10月31日电（记者王浩明）针对球队外援特奎维恩·史密斯兴奋剂阳性事件，中国男子篮球职业联赛（CBA）深圳新世纪篮球俱乐部31日发表声明称，尊重中国篮协与中国反兴奋剂中心的检测结果，将全力配合后续全部调查工作。 “俱乐部高度重视此事件，尊重中国篮协与中国反兴奋剂中心的检测结果，将全力配合后续全部调查工作。运动员依法享有申请B样本复检的权利，俱乐部将协助其按流程完成相关申请。”深圳新世纪篮球俱乐部在声明中写道。 该俱乐部在声明中表示，俱乐部一贯坚决反对任何兴奋剂违规行为，恪守兴奋剂问题“零容忍”底线，维护联…"
