    "author": "",
    "description": "1971年10月25日，第二十六届联合国大会以压倒性多数通过2758号决议，恢复中华人民共和国在联合国的一切合法权利，并立即把台湾国民党当局的“代表”从联合国的一切机构中驱逐出去。11月1日，中华人民共和国五星红旗第一次在联合国升起。",
    "content": "1971年10月25日，第二十六届联合国大会以压倒性多数通过2758号决议，恢复中华人民共和国在联合国的一切合法权利，并立即把台湾国民党当局的“代表”从联合国的一切机构中驱逐出去。11月1日，中华人民共和国五星红旗第一次在联合国升起。"
