    "content": "新华社德黑兰10月31日电（记者沙达提）伊朗最高国家安全委员会秘书穆赫辛·雷扎伊10月31日说，他已收到美国副总统万斯有关重启谈判提议的信函，但尚未作出回应。 雷扎伊在接受伊朗国家广播电视台采访时发表上述言论。他说，美方来信语气已发生彻底转变，“这是一个好迹象，表明伊朗民族已经巩固了自身的胜利与权威”。 雷扎伊拒绝透露更多细节。他表示，既然对方尚未公开信函的任何内容，“我目前也不会透露任何信息”。 谈及伊美间沟通的最新进展，雷扎伊表示，通过斡旋方进行的外交进程已于一个月前启动。雷扎伊说，美国政府一直坚持进行谈判，但…"
