    "description": "新华社东京11月1日电（记者梁晨 李子越）据日本气象厅消息，日本三重县东南部海域1日发生6.1级地震。 日本气象厅发布的信息显示，地震发生于当地时间1日7时15分（北京时间1日6时15分）左右，震中位于北纬33.7度、东经137.1度，震源深度约350公里。 日本气象厅说，此次地震不会引发海啸。",
    "content": "新华社东京11月1日电（记者梁晨 李子越）据日本气象厅消息，日本三重县东南部海域1日发生6.1级地震。 日本气象厅发布的信息显示，地震发生于当地时间1日7时15分（北京时间1日6时15分）左右，震中位于北纬33.7度、东经137.1度，震源深度约350公里。 日本气象厅说，此次地震不会引发海啸。"
