    "description": "新华社德黑兰10月31日电（记者沙达提）伊朗武装部队总参谋长阿里·阿卜杜拉希10月31日警告美国和以色列称，如果再次对伊实施军事打击，伊方的回应将“更为严厉且有效”，“一份新的敌方目标与资产清单已被列入议程”。 据伊朗伊斯兰共和国通讯社报道，阿里·阿卜杜拉希表示，这份目标与资产清单覆盖广泛地理范围。为抵御侵略，伊朗武装部队将以“高强度且不受地理限制”的方式对抗美以。若爆发新的战事，伊朗将是决定战争何时结束的一方。 伊朗最高领袖穆杰塔巴当…",
    "content": "新华社德黑兰10月31日电（记者沙达提）伊朗武装部队总参谋长阿里·阿卜杜拉希10月31日警告美国和以色列称，如果再次对伊实施军事打击，伊方的回应将“更为严厉且有效”，“一份新的敌方目标与资产清单已被列入议程”。 据伊朗伊斯兰共和国通讯社报道，阿里·阿卜杜拉希表示，这份目标与资产清单覆盖广泛地理范围。为抵御侵略，伊朗武装部队将以“高强度且不受地理限制”的方式对抗美以。若爆发新的战事，伊朗将是决定战争何时结束的一方。 伊朗最高领袖穆杰塔巴当天稍早时发表声明说，他会见了伊朗武装力量高级指挥官，并下令针对任何可能的美国和以…"
