    "category": "新闻",
    "title": "特稿：军事基地战时避难所变身消费空间 重庆防空洞释放新活力",
    "link": "https://www.zaobao.com/news/china/story20261101-9886291",
    "pub_date": "2026-11-01 05:00:00",
    "author": "",
    "description": "六米高、六米宽的防空洞，一眼望不到尽头，200多张火锅桌在一个约4000平方米的洞内摆开，神秘的氛围与浓浓的烟火气交织在一起，形成独特的消费场景。 这种在重庆已延续数十年的特色防空洞火锅，吸引越来越多外地及外国游客专程前来。但他们可能不知道，自己此刻坐着吃火锅的地方，曾是中国重要而隐秘的军事基地。 重庆“地下之城”防空洞群前身是军工基地，在保密封闭近50年后，开发改造成了火锅店等消费场所。（刘柳摄） 位于重庆两江新区的“地下之城”防空洞…",
