    "description": "新华社北京10月31日电（记者刘艺、贾淑宜）记者从10月31日开幕的第七届载人航天学术大会了解到，我国载人月球探测工程采用“两次发射、环月对接”方案，工程登月阶段任务各项研制建设工作正在扎实稳步推进。 中国载人航天工程副总设计师、月球探测工程总设计师王翔接受采访时介绍，“两次发射、环月对接”方案，即两枚火箭分别将揽月月面着陆器与梦舟载人飞船精准送入地月转移轨道，之后在环月轨道交会对接。航天员从梦舟飞船进入揽月着陆器进行着陆，开展相关科研…",
    "content": "新华社北京10月31日电（记者刘艺、贾淑宜）记者从10月31日开幕的第七届载人航天学术大会了解到，我国载人月球探测工程采用“两次发射、环月对接”方案，工程登月阶段任务各项研制建设工作正在扎实稳步推进。 中国载人航天工程副总设计师、月球探测工程总设计师王翔接受采访时介绍，“两次发射、环月对接”方案，即两枚火箭分别将揽月月面着陆器与梦舟载人飞船精准送入地月转移轨道，之后在环月轨道交会对接。航天员从梦舟飞船进入揽月着陆器进行着陆，开展相关科研工作。 “两器月轨‘握手’有利于载人月球探测任务持续发展。首先，这一方案与现有技…"
