    "content": "苹果 宣布 ，首批旨在进一步提升iPhone用户体验的Apple智能功能即将在国内推出，将深度整合于用户日常使用的各种app与体验中，助力用户轻松书写、表达自我，并高效处理各项事务。经过长时间的等待，Apple智能功能终于与国内用户见面。 苹果确认已经与阿里巴巴达成合作，在部分Apple智能体验中加入对千问的支持，用户能直接在Siri、写作工具和视觉智能中使用，包括文本与图像理解相关功能。不过苹果也说明了，本次更新不包含Siri AI及其在WWDC 2026上宣布的其他下一代Apple智能功能。 Apple智能由苹…"
