    "content": "新华社北京10月31日电（记者王承昊）香港大学卓越人才论坛北京站活动31日在香港大学北京中心举办。本次论坛邀请来自高校、科研机构、企业及各界嘉宾，共同探讨科技变革时代的人才培养、创新发展与大学使命。 香港大学副校长林晨致辞表示，人工智能既带来机遇，也带来挑战。卓越人才要具有问题意识、扎实的理论基础、独立和创新的思维判断，并在不确定性面前能做出负责任的选择。希望和大家一同以创新回应时代，以开放连接世界，共同为国家培养更多心怀家国、放眼全球、勇于担当的卓越人才。 本次论坛包括“大师课”、主旨演讲、圆桌讨论等环节，内容涵…"
