    "content": "新华社成都10月31日电（记者薛晨）记者从四川省甘孜藏族自治州康定市相关部门获悉，10月26日，康定市境内勒多曼因峰发生一起登山滑坠事故，造成2人遇难、1人受伤。经当地有关部门证实，4名涉事人员均未履行审批报备手续，系绕过卡点私自进入未开发区域的违规登山。 据了解，事故发生在4人攀登勒多曼因峰下撤途中，事发地点海拔约5400米。事故发生后，当地政府、街道、消防、应急、村委会和群众约六七十人组成救援队第一时间赶赴现场施救，村委会组织马匹运送救援物资，成功将两名人员救出。两名遇难者遗体于10月30日被转运下山。事故具体…"
