    "content": "赶上最近换季，我们家进行了一波大扫除，换了换床单、被罩、被芯什么的。结果一铺床、抖床单，家里的孩子，立马开始打喷嚏、咳嗽...... 我以为是秋燥。加湿器开了，水也逼着家人多喝，被套枕套也都换的新的。结果连着大半个月，每天早上醒来喉咙都是干的，鼻子也干痒。 查了一圈，最后剩下 从新家装修到现在超过6年，家人天天贴身睡、却几乎没正眼看过的那两张床垫。 掀开床笠的时候，我趴在床边闻了一下，说不清是什么味，就是有那种东西放久了的味道。凑近了才有，隔着一层床单、再盖一床被子，平时根本察觉不到。 当我把床垫外层拆开之后，我震…"
