    "content": "到了秋冬了，我想搞两个壶。 比如第一个壶默认设定在 55 度，第二个壶默认设定在 90 度。 简单来说，就是类似带保温功能的烧水壶+保温杯。 它不是烧水壶，烧水壶不保温，如果让烧水壶每时每天定点保持那个温度，这得费电呀，对不对？ 比如，我也不知道有没有那种五六升的大保温桶，类似于就是大号的保温杯，但是带电加热的功能。有没有这种东西？ 烧水壶的优点是底座分离，拿起来就走。某种类型的固定水吧，它是底座跟桶连在一起。。。 搜了一下没搜到，万能的 V 友应该见多识广。"
